import { photoManifest, type PhotoName } from "@/data/images.generated";

const BASE = "/images/photos";

/**
 * <picture> with AVIF + WebP srcsets generated by scripts/optimize-images.mjs.
 * Intrinsic width/height are always set, so the browser reserves space (no layout shift).
 */
export function ResponsiveImage({
  name,
  alt,
  sizes,
  priority = false,
  className = "",
}: {
  name: PhotoName;
  alt: string;
  /** e.g. "(min-width: 1024px) 25vw, 100vw" */
  sizes: string;
  /** Above-the-fold LCP image: eager + high fetch priority */
  priority?: boolean;
  className?: string;
}) {
  const { width, height, widths } = photoManifest[name];
  const srcSet = (ext: string) => widths.map((w) => `${BASE}/${name}-${w}.${ext} ${w}w`).join(", ");
  const fallback = widths.includes(1200 as never) ? 1200 : widths[widths.length - 1];

  return (
    <picture>
      <source type="image/avif" srcSet={srcSet("avif")} sizes={sizes} />
      <source type="image/webp" srcSet={srcSet("webp")} sizes={sizes} />
      <img
        src={`${BASE}/${name}-${fallback}.webp`}
        alt={alt}
        width={width}
        height={height}
        loading={priority ? "eager" : "lazy"}
        fetchPriority={priority ? "high" : "auto"}
        decoding={priority ? "sync" : "async"}
        className={className}
      />
    </picture>
  );
}
